    instruction_starts: set[int] = set()
    for rva, hex_bytes, asm in GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_44_INSTRUCTIONS:
        expected = bytes.fromhex(hex_bytes)
