def collect_guarded_gf_target_c_helper_1_third_callee_continuation_62_provenance(pe: PE) -> dict:
    """Capture canonical bytes overlapping the cut DD opcode at 0x1831B2."""

    predecessor = collect_guarded_gf_target_c_helper_1_third_callee_continuation_61_prefix_proof(pe)
    target_rva = GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_RVA
    target_section = next(
        (section.name for section in pe.sections if section.contains_rva(target_rva)),
        "",
    )
    probe = pe.bytes_at_rva(
        target_rva, GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_LEN
    )
    overlap = GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_OVERLAP_BYTES
    overlap_actual = probe[: len(overlap)]
    overlap_matches = overlap_actual == overlap
    predecessor_overlap_matches = (
        predecessor["incomplete_expected_bytes"] == overlap.hex(" ")
        and predecessor["incomplete_actual_bytes"] == overlap.hex(" ")
    )
    inbound = collect_raw_inbound_rel32_candidates(pe, target_rva)
    outbound = collect_raw_rel32_call_candidates(
        pe, target_rva, GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_LEN
    )
    predecessor_exact = (
        predecessor["status"] == "EXACT_183173_TO_1831B2_CONTROL_FLOW_CAPTURE_EDGE_PROVEN"
        and predecessor["prefix_end_rva"] == target_rva
        and predecessor["incomplete_rva"] == target_rva
        and predecessor["incomplete_matches"]
        and predecessor["capture_edge_matches"]
    )
    probe_end_matches = (
        target_rva + len(probe)
        == GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_END_RVA
    )
    captured = bool(
        predecessor_exact
        and target_section == ".text"
        and len(probe) == GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_LEN
        and overlap_matches
        and predecessor_overlap_matches
        and probe_end_matches
    )
    return {
        "target_rva": target_rva,
        "target_section": target_section,
        "predecessor_status": predecessor["status"],
        "predecessor_exact": predecessor_exact,
        "predecessor_end_rva": predecessor["prefix_end_rva"],
        "predecessor_incomplete_rva": predecessor["incomplete_rva"],
        "probe_len": GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_LEN,
        "probe_end_rva": GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_62_PROBE_END_RVA,
        "probe_end_matches": probe_end_matches,
        "overlap_expected_bytes": overlap.hex(" "),
        "overlap_actual_bytes": overlap_actual.hex(" "),
        "overlap_matches": overlap_matches,
        "predecessor_overlap_matches": predecessor_overlap_matches,
        "first_16_bytes": probe[:16].hex(" "),
        "last_16_bytes": probe[-16:].hex(" "),
        "bytes": probe.hex(" "),
        "raw_inbound_rel32_candidates": inbound,
        "raw_outbound_rel32_candidates": outbound,
        "status": (
            "EXACT_EXE_1831B2_TO_1831F2_PROVENANCE_CAPTURED"
            if captured
            else "CALLEE_1831B2_CONTINUATION_PROVENANCE_CAPTURE_FAILED"
        ),
        "start_boundary_status": "PREDECESSOR_INCOMPLETE_X87_OPCODE_DD_START_1831B2",
        "function_entry_status": "UNRESOLVED_AT_1831B2_AND_FORWARD_BYTES",
        "semantic_effect": "UNRESOLVED_CONTINUATION_BYTES_ONLY",
        "call_semantics": "UNRESOLVED",
        "ownership_effect": "NONE",
        "continuation_scope": "RAW_BYTES_OVERLAP_AND_REL32_CENSUS_ONLY",
    }


