        target_within_prefix = (
            GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_87_RVA
            <= expected_target_rva
            < GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_87_PREFIX_END_RVA
        )
        target_is_boundary = decoded_target_rva in instruction_starts
