def collect_guarded_gf_target_c_helper_1_third_callee_continuation_89_prefix_proof(pe: PE) -> dict:
    """Exact-decode the complete 0x18384F..0x18388F canonical capture."""

    provenance = collect_guarded_gf_target_c_helper_1_third_callee_continuation_89_provenance(pe)
    predecessor = collect_guarded_gf_target_c_helper_1_third_callee_continuation_88_prefix_proof(pe)
    expected_next = GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_RVA
    contiguous = True
    rows: list[dict] = []
    instruction_starts: set[int] = set()
    for rva, hex_bytes, asm in GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_INSTRUCTIONS:
        expected = bytes.fromhex(hex_bytes)
        if rva != expected_next:
            contiguous = False
        actual = pe.bytes_at_rva(rva, len(expected))
        rows.append({
            "rva": rva,
            "asm": asm,
            "expected_bytes": expected.hex(" "),
            "actual_bytes": actual.hex(" "),
            "bytes_match": actual == expected,
        })
        instruction_starts.add(rva)
        expected_next = rva + len(expected)

    def branch_target(rva: int) -> int | None:
        raw2 = pe.bytes_at_rva(rva, 2)
        if len(raw2) >= 2 and (raw2[0] == 0xEB or 0x70 <= raw2[0] <= 0x7F):
            rel = struct.unpack_from("<b", raw2, 1)[0]
            return (rva + 2 + rel) & 0xFFFFFFFF
        raw5 = pe.bytes_at_rva(rva, 5)
        if len(raw5) >= 5 and raw5[0] == 0xE9:
            rel = struct.unpack_from("<i", raw5, 1)[0]
            return (rva + 5 + rel) & 0xFFFFFFFF
        raw6 = pe.bytes_at_rva(rva, 6)
        if len(raw6) >= 6 and raw6[0] == 0x0F and 0x80 <= raw6[1] <= 0x8F:
            rel = struct.unpack_from("<i", raw6, 2)[0]
            return (rva + 6 + rel) & 0xFFFFFFFF
        return None

    predecessor_instruction_starts = {
        row["rva"] for row in predecessor["instructions"]
    }
    branch_rows = []
    branch_targets_match = True
    internal_branch_targets_on_boundaries = True
    predecessor_branch_targets_on_boundaries = True
    external_targets: list[int] = []
    for branch_rva, expected_target_rva in GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_BRANCHES:
        decoded_target_rva = branch_target(branch_rva)
        matches = decoded_target_rva == expected_target_rva
        target_within_prefix = (
            GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_RVA
            <= expected_target_rva
            < GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_PREFIX_END_RVA
        )
        target_is_current_boundary = decoded_target_rva in instruction_starts
        target_on_predecessor_boundary = decoded_target_rva in predecessor_instruction_starts
        branch_rows.append({
            "branch_rva": branch_rva,
            "expected_target_rva": expected_target_rva,
            "decoded_target_rva": decoded_target_rva,
            "matches": matches,
            "target_within_prefix": target_within_prefix,
            "target_is_instruction_boundary": (
                target_is_current_boundary if target_within_prefix
                else target_on_predecessor_boundary
            ),
            "target_is_current_boundary": target_is_current_boundary,
            "target_on_predecessor_boundary": target_on_predecessor_boundary,
        })
        branch_targets_match = branch_targets_match and matches
        if target_within_prefix:
            internal_branch_targets_on_boundaries = (
                internal_branch_targets_on_boundaries and target_is_current_boundary
            )
        else:
            external_targets.append(expected_target_rva)
            predecessor_branch_targets_on_boundaries = (
                predecessor_branch_targets_on_boundaries
                and target_on_predecessor_boundary
            )

    inherited_targets = list(
        GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_INHERITED_FORWARD_TARGETS
    )
    resolved_predecessor_targets = [
        {"rva": rva, "is_instruction_boundary": rva in instruction_starts}
        for rva in GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_RESOLVED_PREDECESSOR_TARGET_RVAS
    ]
    resolved_predecessor_targets_on_boundaries = all(
        item["is_instruction_boundary"] for item in resolved_predecessor_targets
    )
    resolved_predecessor_target_rvas = {
        item["rva"] for item in resolved_predecessor_targets
    }
    remaining_predecessor_targets = [
        rva for rva in inherited_targets if rva not in resolved_predecessor_target_rvas
    ]
    expected_predecessor_boundary_targets = set(
        GF_TARGET_C_HELPER_1_THIRD_CALLEE_CONTINUATION_89_EXPECTED_PREDECESSOR_BOUNDARY_TARGET_RVAS
    )
    predecessor_target_contract = bool(
        predecessor["status"] == "EXACT_183810_TO_18384F_CONTROL_FLOW_CAPTURE_EDGE_PROVEN"
        and predecessor["unresolved_forward_targets"] == inherited_targets
        and provenance["inherited_predecessor_forward_targets"] == inherited_targets
        and provenance["expected_inherited_forward_targets"] == inherited_targets
        and predecessor["incomplete_rva"] == provenance["target_rva"]
        and predecessor["incomplete_matches"]
        and predecessor["capture_edge_matches"]
        and provenance["overlap_matches"]
        and provenance["predecessor_overlap_matches"]
        and resolved_predecessor_target_rvas == {0x00183854}
        and resolved_predecessor_targets_on_boundaries
        and remaining_predecessor_targets == []
    )
    predecessor_exact = bool(
        provenance["status"] == "EXACT_EXE_18384F_TO_18388F_PROVENANCE_CAPTURED"
        and provenance["predecessor_exact"]
        and provenance["overlap_matches"]
        and provenance["predecessor_overlap_matches"]
        and provenance["probe_end_matches"]
        and provenance["exact_bytes_match"]
    )
